import manifest from './musicLibrary.json'

/**
 * The bundled, offline music library.
 *
 * Every track is an original synthesis generated by
 * `scripts/generate-music.py` and dedicated to the public domain under
 * CC0 1.0. Nothing is fetched from the network at runtime: the audio files
 * live in `public/music/` and are copied into the local project only when
 * the user adds one.
 */

export interface MusicLibraryTrack {
  id: string
  title: string
  artist: string
  /** File name inside `public/music/`. */
  file: string
  /** Seconds. */
  duration: number
  bpm: number
  mood: string[]
  license: string
  source: string
}

export interface MusicLibraryManifest {
  version: number
  license: string
  licenseUrl: string
  attribution: string
  tracks: MusicLibraryTrack[]
}

export const MUSIC_LIBRARY = manifest as MusicLibraryManifest

/** Local (never remote) URL for a bundled track. */
export function musicTrackUrl(file: string): string {
  return `${import.meta.env.BASE_URL}music/${encodeURIComponent(file)}`
}

/** Formats a duration in seconds as m:ss for the library cards. */
export function formatMusicDuration(seconds: number): string {
  const total = Math.max(0, Math.round(seconds))
  const m = Math.floor(total / 60)
  const s = total % 60
  return `${m}:${s.toString().padStart(2, '0')}`
}

/** Finds a track by id (pure; used by tests and the dialog). */
export function findMusicTrack(id: string): MusicLibraryTrack | null {
  return MUSIC_LIBRARY.tracks.find((t) => t.id === id) ?? null
}
